import{_t as e,it as t,n,rt as r}from"./chunks/framework.GGfqtSwG.js";var i=JSON.parse(`{"title":"Ressourcer","description":"","frontmatter":{},"headers":[],"relativePath":"resourcer.md","filePath":"resourcer.md"}`),a={name:`resourcer.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="ressourcer" tabindex="-1">Ressourcer <a class="header-anchor" href="#ressourcer" aria-label="Permalink to “Ressourcer”">​</a></h1><p>Der findes mange forskellige hjemmesider og forumer med information om DIY hormonbehandling. En af de største ressourcer er <a href="https://www.reddit.com/r/TransDIY/" target="_blank" rel="noreferrer">r/TransDIY</a>. Deres <a href="https://www.reddit.com/r/TransDIY/wiki/index/" target="_blank" rel="noreferrer">wiki</a> og <a href="https://www.reddit.com/r/TransDIY/wiki/faq/" target="_blank" rel="noreferrer">FAQ</a> har virkelig meget fantastisk information om DIY hormonbehandling og er et godt sted at starte. Hvis reddit siger du skal bekræfte din identitet for at se det, vil jeg anbefale at bruge en VPN eller bruge en reddit frontend som <a href="https://github.com/redlib-org/redlib-instances/blob/main/instances.md" target="_blank" rel="noreferrer">Redlib</a>.</p><p>En anden virkelig god side er <a href="https://diyhrt.info/" target="_blank" rel="noreferrer">diyhrt.info</a>. De har rigtig meget information om DIY hormonbehandling, og jeg vil anbefale at du læser hele deres transfem/transmasc guide hvis du er interesseret i DIY hormonbehandling eller bare hormonbehandling generelt.</p><p><a href="https://transharmreduction.org/" target="_blank" rel="noreferrer">Trans Harm Reduction</a> er en virkelig god side til forskellige ting, men noget af det vigtigste de laver er at teste hormonerne fra forskellige sælgere så vi kan være sikre på, at hormonerne er sikre og effektive.</p><p><a href="https://transfemscience.org/" target="_blank" rel="noreferrer">TransfemScience</a> er endnu en fantastisk side med masser af information om hormonbehandling. Jeg vil højt anbefale at læse deres artikel <a href="https://transfemscience.org/articles/transfem-intro/" target="_blank" rel="noreferrer">An Introduction to Hormone Therapy for Transfeminine People</a> da den har virkelig meget vigtig information som er god at vide hvis man vil starte DIY hormonbehandling.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};